package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.character.*;
import dev.tacticalcombat.uiapi.*;
import java.nio.file.*;
import java.util.*;
import org.lwjgl.glfw.GLFW;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

/** Real persistence operations plus measured geometry and inline alignment input behavior. */
public final class IdentityCheckpointTests {
    private static int count;
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);count++;}
    private static JsonObject ok(UiApiService api,CharacterRepository.Principal p,UiApiService.Operation op,JsonObject args){var r=api.handle(p,op,args);check(r.code().equals("OK"),op+": "+r.message());return r.data();}
    public static void run()throws Exception {
        check(Arrays.stream(CreatorFlow.Step.values()).map(s->s.title).toList().equals(List.of("Identity","Class","Ability Points","Proficiencies","Equipment","Features","Spells","Character Details","Review & Finish")),"Exactly nine visible tabs in required order");
        check(Arrays.stream(CreatorFlow.Step.values()).noneMatch(s->Set.of("Background","Overview","Method").contains(s.title)),"No obsolete creator tabs");
        check(!CharacterDetailsScreen.KEYS.contains("age")&&!CharacterDetailsScreen.KEYS.contains("height")&&!CharacterDetailsScreen.KEYS.contains("alignment"),"Identity fields have no duplicate story editor");
        check(new HashSet<>(IdentityModel.ALIGNMENTS).size()==9&&IdentityModel.ALIGNMENTS.contains("True Neutral"),"Nine conventional alignments");
        for(int[] size:List.of(new int[]{240,135},new int[]{320,180},new int[]{480,270},new int[]{640,360},new int[]{960,540},new int[]{1280,720}))for(int scale:List.of(1,2)){
            var shell=CharacterShell.layout(UiLayout.frame(size[0],size[1],980));java.util.function.ToIntFunction<String> measure=s->s.chars().map(c->(c=='i'||c=='l'?2:c=='D'?7:6)*scale).sum();var l=IdentityLayout.layout(shell.content().width(),shell.content().height(),measure);check(l.cards().size()==9,"All nine race cards exist");var first=l.cards().getFirst();
            for(int i=0;i<9;i++){var r=l.cards().get(i);check(r.width()==first.width()&&r.height()==first.height(),"Uniform race tile dimensions");check(r.x()==first.x()+i%3*(first.width()+4)&&r.y()==first.y()+i/3*(first.height()+4),"Exactly three columns by three rows");check(r.x()>=l.grid().x()&&r.x()+r.width()<=l.grid().x()+l.grid().width(),"Click rectangle is inside grid");var label=Srd2014Catalog.SPECIES.get(i).name();var lines=IdentityLayout.lines(label,r.width()-12,measure);check(String.join("",lines).equals(label)&&lines.stream().allMatch(line->measure.applyAsInt(line)<=r.width()-12),"Full measured label, including Dragonborn, never truncates");check(lines.size()*10+12<=r.height(),"Measured wrapped lines fit card vertically");for(int j=i+1;j<9;j++)check(!r.overlaps(l.cards().get(j)),"Race hitboxes do not overlap");}
            if(!l.stacked())check(!l.grid().overlaps(l.information()),"Race and information panels remain separate");
            if(size[0]>=480&&scale==1)check(l.grid().y()+l.grid().height()<=shell.content().height(),"All nine race cards fit normal logical viewport");
            for(int y:List.of(shell.content().y()+4,shell.content().y()+40,shell.content().y()+shell.content().height()-18)){var field=new UiLayout.Rect(shell.content().x()+3,y,100,17);var popup=AlignmentDropdown.popup(field,shell.content());check(popup.y()>=shell.content().y()&&popup.y()+popup.height()<=shell.content().y()+shell.content().height(),"Alignment popup stays inside workspace");}
        }
        var canvas=new CharacterCanvas(new UiLayout.Rect(0,0,240,160));var layout=IdentityLayout.layout(240,160,s->s.length()*6);var raceClicks=new ArrayList<String>();canvas.control("races",new IdentityRaceGrid(layout,"",v->{check(canvas.focusedKey().equals("races"),"Race focus established before preview rebuild callback");raceClicks.add(v);}));var selections=new ArrayList<String>();canvas.control("alignment",new AlignmentDropdown(5,40,120,()->"",selections::add,()->new UiLayout.Rect(0,0,240,160)));check(canvas.mouseClicked(10,44,0)&&canvas.mouseClicked(10,70,0)&&selections.size()==1&&raceClicks.isEmpty(),"Popup gets hit before underlying race card");check(canvas.mouseClicked(10,70,0)&&raceClicks.size()==1,"Collapsed alignment leaves race card clickable");
        Path dir=Files.createTempDirectory("identity-a");var repo=new CharacterRepository(dir.resolve("campaigns.json"));var library=new LibraryRepository(dir.resolve("library.json"));var api=new UiApiService(repo,library,(op,a)->{throw new IllegalArgumentException("world unavailable");});var owner=new CharacterRepository.Principal(UUID.randomUUID(),false);var outsider=new CharacterRepository.Principal(UUID.randomUUID(),false);
        var draft=ok(api,owner,LIBRARY_CREATE,args("profile","srd_5_1","mode","GUIDED","sheet",dev.tacticalcombat.rules.srd.SrdAuthoring.template().toString()));String id=text(draft,"id");var identity=SheetSections.read(draft.getAsJsonObject("sheet"),"identity");check(text(identity,"background").isEmpty(),"New guided draft has no assigned background");check(WizardModel.statuses(draft).get(WizardModel.Stage.BACKGROUND).complete(),"Deferred background is not a progress requirement");check(CreatorFlow.statuses(draft).size()==9,"Preview progress follows nine tabs");check(array(ok(api,owner,LIBRARY_VALIDATE,args("character",id)),"errors").isEmpty(),"No background validation dependency");var complete=ok(api,owner,LIBRARY_FINALIZE,args("character",id,"revision",revision(draft)));check(text(complete,"stage").equals("COMPLETE"),"Blank background can finalize");draft=complete;
        identity.addProperty("background","Existing personal background");identity.addProperty("biography","Saved story\nkept intact");identity.addProperty("alignment","Older custom alignment");identity.addProperty("species","High Elf");draft=ok(api,owner,LIBRARY_UPDATE,args("character",id,"revision",revision(draft),"section","identity","data",identity));var state=new CreatorDraftState(draft);check(state.fields.get("alignment").equals("Older custom alignment"),"Reopening preserves legacy alignment");check(IdentityModel.subrace(state.fields.get("species")).equals("High Elf"),"Legacy standalone subrace understood");
        IdentityModel.race(state,"Dwarf");check(state.fields.get("species").equals("Dwarf")&&IdentityModel.subrace(state.fields.get("species")).isEmpty(),"Race transition clears incompatible elven subrace");check(IdentityModel.status(state).startsWith("Unsaved"),"Preview never falsely claims persistence");IdentityModel.subrace(state,"Hill Dwarf");check(state.fields.get("species").equals("Dwarf — Hill Dwarf"),"Compatible dwarf variant recorded");IdentityModel.subrace(state,"");check(state.fields.get("species").equals("Dwarf")&&IdentityModel.completeness("Dwarf").contains("Base traits only"),"Base/original can be selected directly, labeled incomplete/manual");IdentityModel.subrace(state,"Hill Dwarf");IdentityModel.race(state,"Tiefling");check(IdentityModel.subrace(state.fields.get("species")).isEmpty()&&CreatorFlow.subraces("Tiefling").isEmpty(),"No BG3-only Tiefling variants or stale dwarf subrace");try{IdentityModel.subrace(state,"Hill Dwarf");throw new AssertionError("Incompatible variant accepted");}catch(IllegalArgumentException expected){count++;}
        IdentityModel.race(state,"Elf");IdentityModel.subrace(state,"High Elf");var saved=ok(api,owner,LIBRARY_UPDATE,args("character",id,"revision",revision(state.snapshot()),"section","identity","data",state.identityData(List.of("species","age","height","alignment"))));state.accept(DraftReplies.snapshot(saved,id),true);check(IdentityModel.status(state).equals("Saved selection"),"Only complete acknowledgement changes saved status");
        var picked=new ArrayList<String>();var dropdown=new AlignmentDropdown(5,40,120,()->state.fields.get("alignment"),v->{picked.add(v);IdentityModel.alignment(state,v);},()->new UiLayout.Rect(0,0,180,160));dropdown.setFocused(true);check(dropdown.keyPressed(GLFW.GLFW_KEY_ENTER,0,0)&&dropdown.isOpen(),"Keyboard opens inline dropdown");check(dropdown.keyPressed(GLFW.GLFW_KEY_ESCAPE,0,0)&&!dropdown.isOpen()&&picked.isEmpty(),"Escape dismisses without changing legacy alignment");check(dropdown.mouseClicked(10,44,0)&&dropdown.isOpen(),"Mouse opens alignment in place");check(dropdown.mouseClicked(10,60,0)&&!dropdown.isOpen()&&picked.size()==1,"Mouse chooses actual option without secondary screen");
        for(String alignment:IdentityModel.ALIGNMENTS){IdentityModel.alignment(state,alignment);saved=ok(api,owner,LIBRARY_UPDATE,args("character",id,"revision",revision(state.snapshot()),"section","identity","data",state.identityData(List.of("species","age","height","alignment"))));state.accept(saved,true);var reopened=ok(api,owner,LIBRARY_GET,args("character",id));check(CreatorDraftState.savedField(reopened,"alignment").equals(alignment),"Alignment persists: "+alignment);check(text(SheetSections.read(reopened.getAsJsonObject("sheet"),"identity"),"background").equals("Existing personal background"),"Identity updates preserve deferred background");}
        IdentityModel.race(state,"Gnome");IdentityModel.subrace(state,"Rock Gnome");var latest=state.snapshot();var otherEdit=SheetSections.read(latest.getAsJsonObject("sheet"),"identity");otherEdit.addProperty("biography","Newer story by same owner");var changed=ok(api,owner,LIBRARY_UPDATE,args("character",id,"revision",revision(latest),"section","identity","data",otherEdit));var rejected=api.handle(owner,LIBRARY_UPDATE,args("character",id,"revision",revision(latest),"section","identity","data",state.identityData(List.of("species"))));check(rejected.code().equals("CONFLICT")&&IdentityModel.status(state).startsWith("Unsaved")&&CreatorDraftState.savedField(state.snapshot(),"species").equals("Elf — High Elf"),"Failed save retains preview and last acknowledged race");state.accept(changed,false);check(state.fields.get("species").equals("Gnome — Rock Gnome")&&state.reviewRequired(),"Refresh retains local race and requires review after conflict");state.reviewed();saved=ok(api,owner,LIBRARY_UPDATE,args("character",id,"revision",revision(state.snapshot()),"section","identity","data",state.identityData(List.of("species"))));state.accept(saved,true);check(text(SheetSections.read(saved.getAsJsonObject("sheet"),"identity"),"biography").equals("Newer story by same owner"),"Retry merges race into latest story without overwrite");check(IdentityModel.status(state).equals("Saved selection"),"Accepted retry publishes saved race");
        var before=state.snapshot().toString();try{state.accept(DraftReplies.snapshot(new JsonObject(),id),true);throw new AssertionError("Partial acknowledgement accepted");}catch(IllegalArgumentException expected){count++;}check(state.snapshot().toString().equals(before),"Malformed reply cannot publish saved success");check(api.handle(outsider,LIBRARY_UPDATE,args("character",id,"revision",revision(state.snapshot()),"section","identity","data",state.identityData(List.of("species")))).code().equals("FORBIDDEN"),"Private identity ownership enforced");
        var restarted=new LibraryRepository(dir.resolve("library.json")).get(owner,UUID.fromString(id));var reopened=UiApiService.draft(restarted,true);check(CreatorDraftState.savedField(reopened,"species").equals("Gnome — Rock Gnome")&&CreatorDraftState.savedField(reopened,"alignment").equals("Chaotic Evil"),"Race and alignment survive repository restart");check(text(SheetSections.read(reopened.getAsJsonObject("sheet"),"identity"),"background").equals("Existing personal background"),"Background backward compatibility survives restart");
        System.out.println("Identity checkpoint A checks passed: "+count);
    }
}
